def rearrangeArray(nums):
    # Count occurrences of every value (values are in 1..100)
    cnt = [0] * 101
    for x in nums:
        cnt[x] += 1

    ans = []
    # Keep making rounds until every element has been placed
    while len(ans) < len(nums):
        # One round: take one occurrence of every value still present, ascending
        for v in range(1, 101):
            if cnt[v] > 0:
                ans.append(v)
                cnt[v] -= 1
    return ans
